// 先沿原场景可见的同地真人，再检查模板端点；远方/未出生者不进入有限页。
#include "known_personal_dialogue_view.hpp"
#include "resident/views/common_presentation.hpp"
#include <limits>
namespace hanmo::resident {namespace {
using V=BoundaryValue;using A=V::Array;
V identity(const WorldIdentity& s){StableId id;constexpr char hex[]="0123456789abcdef";for(auto b:s.world_id){id+=hex[b>>4];id+=hex[b&15];}return boundary::obj({{"world_id",V{id}},{"execution_epoch",V{s.execution_epoch}},{"revision",V{s.revision}},{"tick",V{s.tick}}});}
StableId at(const InteractionAccess& a,const StableId& id){auto where=a.resolve_location(id);const auto* place=std::get_if<SettlementLocation>(&where);return place?place->place_id:StableId{};}
Outcome<bool> selected(const KnownPersonalDialogueContext& x,const KnownPersonalDialogueSelector& s,const StableId& id){if(s.kind=="installed_actor")return {true,s.source_id==id,{}};if(s.kind!="born_prototype"||!x.sources.born)return {false,{},common_failure("KnownPersonalActorBirthSourceRequired").error};auto source=x.sources.born(id);if(!source.ok)return {false,{},source.error};return {true,source.value&&source.value->prototype_id==s.source_id&&source.value->adult&&source.value->alive,{}};}
}
Outcome<BoundaryValue> query_known_personal_dialogues(const KnownPersonalDialogueContext& x,Integer cursor){
 constexpr Integer limit=16;const auto& actor=x.common.state().metadata.player_actor_id;if(cursor<0||cursor>std::numeric_limits<Integer>::max()-limit)return {false,{},common_failure("InvalidKnownPersonalDialogueCursor").error};if(!x.common.actor(actor)||!x.interaction_access.resolve_location||!x.definitions.common)return {false,{},common_failure("KnownPersonalDialogueSourceRequired").error};auto valid=validate_known_personal_dialogues(x);if(!valid.ok)return {false,{},valid.error};valid=validate_known_personal_dialogue_cached_results(x.common,&x.state);if(!valid.ok)return {false,{},valid.error};
 A all;const auto here=at(x.interaction_access,actor);CommonPresentation names(x.common.state(),*x.definitions.common);auto ids=x.common.actor_order();std::sort(ids.begin(),ids.end());
 if(!here.empty())for(const auto& id:ids){const auto* person=x.common.actor(id);if(!person||id==actor||!person->alive||at(x.interaction_access,id)!=here)continue;for(const auto& t:x.catalog.templates){auto listener=selected(x,t.listener,actor);if(!listener.ok)return {false,{},listener.error};if(!listener.value)continue;auto provider=selected(x,t.provider,id);if(!provider.ok)return {false,{},provider.error};if(!provider.value)continue;
  OpenKnownPersonalDialogue request{id,t.id};auto quote=preview_known_personal_dialogue(x,actor,request);if(!quote.ok&&quote.error.kind!=ErrorKind::rule)return {false,{},quote.error};if(!quote.ok&&quote.error.original.code=="KnownPersonalActorAdultRequired")continue;auto name=names.display_name(id);if(!name.ok)return {false,{},name.error};A actions;actions.push_back(boundary::obj({{"command",V{"open_known_personal_dialogue"}},{"params",encode_known_personal_dialogue_command(request)},{"text",V{"与本人交谈"}},{"summary",V{"在此处开始本人私人交谈。之后的认可、接受或撤回都须本人实际说出对应声明，再分别办理。"}},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}}}));all.push_back(boundary::obj({{"id",V{t.id+"|"+id}},{"display_name",V{name.value}},{"status_text",V{"本人正在此处"}},{"progress_text",V{"开始交谈不等于确认关系、代人同意或移交任何权利。"}},{"actions",V{std::move(actions)}}}));}}
 A rows;const auto end=std::min(all.size(),static_cast<std::size_t>(cursor+limit));for(std::size_t i=static_cast<std::size_t>(cursor);i<end;++i)rows.push_back(std::move(all[i]));V::Dict page{{"ok",V{true}},{"source_identity",identity(x.common.state().identity)},{"observer_actor_id",V{actor}},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(end<all.size())page.emplace_back("next_cursor",V{cursor+limit});return {true,V{std::move(page)}, {}};
}
}
